const path = require('path');
const pw = require(path.join(process.cwd(), '.playwright-cli', 'node_modules', 'playwright-core'));

(async () => {
  const browser = await pw.chromium.launch({ headless: true });
  const page = await (await browser.newContext()).newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errs.push('console.error: ' + m.text()); });

  await page.goto('http://localhost:3000/finlife-3d.html', { waitUntil: 'networkidle' });
  await page.click('#btn-start');
  await page.waitForTimeout(500);

  await page.keyboard.press('Tab');
  await page.waitForTimeout(150);
  const phoneOpen = await page.evaluate(() => document.getElementById('phone').classList.contains('open'));

  await page.click('#phone-home button[data-app="finances"]');
  await page.waitForTimeout(150);
  const financesShown = await page.evaluate(() => {
    const apc = document.getElementById('phone-app-content');
    return apc.classList.contains('active') && !!apc.querySelector('#tab-finances');
  });

  await page.click('#phone-back');
  await page.waitForTimeout(100);
  const homeShown = await page.evaluate(() => {
    const home = document.getElementById('phone-home');
    const t = document.getElementById('tab-finances');
    return home.style.display !== 'none' && t && t.parentElement.id === 'left-panel';
  });

  await page.keyboard.press('Tab');
  await page.waitForTimeout(100);
  const phoneClosed = await page.evaluate(() => !document.getElementById('phone').classList.contains('open'));

  await page.evaluate(() => { document.getElementById('btn-bank').click(); });
  await page.waitForTimeout(250);
  const bankModal = await page.evaluate(() => {
    const ov = document.getElementById('modal-overlay');
    return !!ov && (ov.classList.contains('open') || getComputedStyle(ov).display !== 'none');
  });

  console.log(JSON.stringify({ phoneOpen, financesShown, homeShown, phoneClosed, bankModal }, null, 2));
  if (errs.length) { console.log('ERRORS:'); errs.forEach(e => console.log(' ' + e)); }
  else console.log('No JS errors');

  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

