function buildBuilding(cfg){
  // Pixel-art building texture on a canvas
  const c = document.createElement('canvas');
  c.width = 256; c.height = 320;
  const ctx = c.getContext('2d');

  // Roof
  ctx.fillStyle = cfg.color;
  ctx.beginPath();
  ctx.moveTo(20, 100); ctx.lineTo(128, 30); ctx.lineTo(236, 100);
  ctx.lineTo(220, 110); ctx.lineTo(128, 50); ctx.lineTo(36, 110);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(20, 100); ctx.lineTo(128, 30); ctx.lineTo(236, 100);
  ctx.stroke();

  // Body
  ctx.fillStyle = '#f4e8d0';
  ctx.fillRect(40, 100, 176, 180);
  // Trim
  ctx.fillStyle = cfg.color;
  ctx.fillRect(40, 100, 176, 8);
  ctx.fillRect(40, 272, 176, 8);
  // Door
  ctx.fillStyle = '#5d4037';
  ctx.fillRect(108, 200, 40, 80);
  ctx.fillStyle = '#ffd700';
  ctx.fillRect(140, 235, 4, 4);
  // Windows
  ctx.fillStyle = '#9fdcff';
  ctx.fillRect(58, 130, 36, 36);
  ctx.fillRect(162, 130, 36, 36);
  ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 2;
  ctx.strokeRect(58, 130, 36, 36); ctx.strokeRect(162, 130, 36, 36);
  ctx.beginPath(); ctx.moveTo(76,130); ctx.lineTo(76,166); ctx.moveTo(58,148); ctx.lineTo(94,148); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(180,130); ctx.lineTo(180,166); ctx.moveTo(162,148); ctx.lineTo(198,148); ctx.stroke();
  // Sign with icon
  ctx.fillStyle = '#fff'; ctx.fillRect(70, 175, 116, 24);
  ctx.strokeStyle = '#1a1a1a'; ctx.strokeRect(70, 175, 116, 24);
  ctx.font = '60px serif';
  ctx.textAlign = 'center';
  ctx.fillStyle = '#000';
  ctx.fillText(cfg.icon, 128, 195);
  // Outline
  ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 3;
  ctx.strokeRect(40, 100, 176, 180);

  const tex = new THREE.CanvasTexture(c);
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.LinearMipMapLinearFilter;

  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map:tex, transparent:true, alphaTest:0.05 }));
  sprite.scale.set(5, 6.25, 1);
  sprite.position.set(cfg.pos[0], 3.1, cfg.pos[1]);
  scene.add(sprite);

  // Floating label
  const lc = document.createElement('canvas');
  lc.width = 256; lc.height = 64;
  const lctx = lc.getContext('2d');
  lctx.fillStyle = 'rgba(0,0,0,.78)';
  lctx.fillRect(0, 14, 256, 40);
  lctx.font = 'bold 24px Segoe UI, sans-serif';
  lctx.textAlign = 'center';
  lctx.fillStyle = '#ffd700';
  lctx.fillText(cfg.label, 128, 42);
  const ltex = new THREE.CanvasTexture(lc);
  const lsprite = new THREE.Sprite(new THREE.SpriteMaterial({ map:ltex, transparent:true }));
  lsprite.scale.set(4.2, 1.05, 1);
  lsprite.position.set(cfg.pos[0], 7.4, cfg.pos[1]);
  scene.add(lsprite);

  buildings3d.push({ sprite, label:lsprite, cfg, pos: new THREE.Vector3(cfg.pos[0], 0, cfg.pos[1]) });
}

