tool_input.content:
const path = require('path');
const pw = require(path.join(process.cwd(), '.playwright-cli', 'node_modules', 'playwright-core'));

(async () => {
  const browser = await pw.chromium.launch({ headless: true });
  const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errs.push('console.error: ' + m.text()); });

  await page.goto('http://localhost:3000/finlife-3d.html', { waitUntil: 'networkidle' });
  await page.click('#btn-start');
  await page.waitForTimeout(1000);

  // 1) Spawn view (player at 15, 1.6, 30 looking -Z toward Home at 15,15)
  await page.screenshot({ path: '.shot-spawn.png' });

  // 2) Top-down city overview
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 0; p.y = 180; p.z = 0; p.yaw = 0; p.pitch = -1.4;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-topdown.png' });

  // 3) Street-level shot at an intersection
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 22; p.y = 1.6; p.z = 22; p.yaw = -2.0; p.pitch = 0;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-street.png' });

  // 4) Confirm key bindings: E opens phone, F interacts
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 15; p.y = 1.6; p.z = 22; p.yaw = 0; p.pitch = 0;
  });
  await page.waitForTimeout(150);
  await page.keyboard.press('e');
  await page.waitForTimeout(200);
  const phoneOpenAfterE = await page.evaluate(() => document.getElementById('phone').classList.contains('open'));
  await page.keyboard.press('e');
  await page.waitForTimeout(200);
  const phoneClosedAfterE = await page.evaluate(() => !document.getElementById('phone').classList.contains('open'));

  // F should interact when near Home (15, 15) â€” player at (15, 22) is near
  await page.keyboard.press('f');
  await page.waitForTimeout(200);
  const sleepDialogShown = await page.evaluate(() => document.getElementById('sleep-dialog').classList.contains('open'));

  console.log(JSON.stringify({
    phoneOpenAfterE,
    phoneClosedAfterE,
    sleepDialogShown,
    buildingCount: await page.evaluate(() => window.__finlife3d._getBuildings().length),
  }, null, 2));

  if (errs.length) { console.log('ERRORS:'); errs.forEach(e => console.log(' ' + e)); }
  else console.log('No JS errors');

  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

