const path = require('path');
const pw = require(path.join(process.cwd(), '.playwright-cli', 'node_modules', 'playwright-core'));

(async () => {
  const browser = await pw.chromium.launch({ headless: true });
  const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errs.push('console.error: ' + m.text()); });

  await page.goto('http://localhost:3000/finlife-3d.html', { waitUntil: 'networkidle' });
  await page.click('#btn-start');
  await page.waitForTimeout(1500);

  const buildingCount = await page.evaluate(() => window.__finlife3d._getBuildings().length);
  console.log('buildingCount =', buildingCount);

  // 1) Top-down city overview (high above)
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 0; p.y = 220; p.z = 0; p.yaw = 0; p.pitch = -1.4;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-top.png' });

  // 2) Open phone via E key, then take a screenshot of the home screen
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 15; p.y = 1.6; p.z = 30; p.yaw = 0; p.pitch = 0;
  });
  await page.waitForTimeout(150);
  await page.keyboard.press('e');
  await page.waitForTimeout(250);
  const phoneOpen = await page.evaluate(() => document.getElementById('phone').classList.contains('open'));
  await page.screenshot({ path: '.shot-phone-home.png' });

  // 3) Tap Maps app
  await page.click('#phone-home button[data-app="maps"]');
  await page.waitForTimeout(300);
  const mapsRendered = await page.evaluate(() => !!document.querySelector('.maps-canvas'));
  await page.screenshot({ path: '.shot-phone-maps.png' });

  // 4) Tap a destination (Bank)
  const tappedBank = await page.evaluate(() => {
    const rows = [...document.querySelectorAll('.maps-row')];
    const row = rows.find(r => /Bank/.test(r.textContent));
    if (row) { row.click(); return true; }
    return false;
  });
  await page.waitForTimeout(300);
  const phoneClosed = await page.evaluate(() => !document.getElementById('phone').classList.contains('open'));
  const routeShowing = await page.evaluate(() => document.getElementById('hud-route').classList.contains('show'));
  await page.screenshot({ path: '.shot-routing.png' });

  // 5) Tap Inbox app â€” should close phone and open the existing inbox modal
  await page.keyboard.press('e');
  await page.waitForTimeout(150);
  await page.click('#phone-home button[data-app="inbox"]');
  await page.waitForTimeout(300);
  const inboxModalOpen = await page.evaluate(() => {
    const ov = document.getElementById('modal-overlay');
    return !!ov && (ov.classList.contains('open') || getComputedStyle(ov).display !== 'none');
  });

  console.log(JSON.stringify({
    buildingCount,
    phoneOpen,
    mapsRendered,
    tappedBank,
    phoneClosed,
    routeShowing,
    inboxModalOpen,
  }, null, 2));

  if (errs.length) { console.log('ERRORS:'); errs.forEach(e => console.log(' ' + e)); }
  else console.log('No JS errors');

  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

# Plan: Home Interior Rooms, Belongings Visualizer, Shower Mechanic, City Polish

**Type:** feature Â· **Complexity:** complex
**Target file:** `finlife-3d.html` (single self-contained HTML game)

## Task Description

Pressing **F** on the Home building should no longer just open a "sleep" modal â€” it should bring the player into a real 3D interior **room** sized and furnished according to the value of their current property. The room must contain a complete checklist of housing essentials (structure, bedroom, kitchen, bathroom, safety, comfort, cleaning, utilities). Player belongings purchased throughout the game (`GS.char.belongings`) must appear inside the room at sensible locations (clothes in the closet, computer on the desk, tools in the car/garage).

A **shower** must be present in the bathroom: standing on it and pressing F counts as a daily shower. Skipping showers reduces **health and happiness by 2 each game tick (month)** the shower is missed, until the player showers again.

Additionally, the city must be **denser at its center** (a "downtown core" of taller skyscrapers around the origin), and **every action building's entrance must face the nearest road** instead of facing the island center as it does today.

## Objective

When the player walks up to Home and presses **F**:
1. They are seamlessly teleported into a 3D walkable interior whose **size and quality scale with `GS.char.houseValue` / `inv.properties.livedIn`**.
2. The interior contains every required essential (full list below) placed in its correct sub-zone.
3. Items in `GS.char.belongings` are visualized as small meshes/icons in the appropriate zone.
4. A shower is interactable; missing it causes a daily penalty until the next shower.
5. Pressing F on the interior door returns the player to the world at the Home doorstep.

Beyond Home: a downtown skyline emerges in the central blocks, and every shop/office/etc.'s door points at a road, not at the island center.

## Problem Statement

Currently `finlife-3d.html` treats Home as a single billboard-faced cube whose only function is to open a sleep dialog. That underserves the user's ambition for the player to *live* in a home that grows with their finances. Belongings purchased through the existing finance simulator (`btn-belongings`, Real Estate, etc.) accumulate in `GS.char.belongings` as a flat list â€” invisible in the world. Hygiene is also entirely abstract; the user wants a tangible mechanic that punishes neglect.

Visually, the city's central blocks render with the same mid-rise filler density as the suburbs, and action buildings rotate to face origin (looks unnatural â€” an entrance on the back of the lot when origin is "behind" the lot's road frontage).

## Solution Approach

1. **Dual-scene architecture**: keep the exterior `scene` exactly as it is. Build a separate `interiorScene` lazily when the player first enters Home. Single shared `camera`/`renderer`. A boolean `inInterior` decides which scene gets rendered each frame and which collision array is used.
2. **Tier table** maps `houseValue` â†’ room size + feature set. Tier upgrades = bigger room, more zones, nicer furniture.
3. **Essentials registry**: declarative list of `{id, zone, builder(group, x, z, qual)}`. The room generator walks this list and places every required item at zone-specific anchor points.
4. **Belongings placement**: a regex-based classifier maps each `belongings[]` entry to a zone (`closet`, `desk`, `garage`, `shelf`, `wall`, `dresser`). Renders each as a small canvas-textured sprite/box at a free anchor in that zone.
5. **Shower mechanic**: `c.lastShowerMonth` field added to char state. A wrapper around `#btn-age` post-tick subtracts 2/2 from `c.health`/`c.happiness` per missed month. Standing on the shower mesh and pressing F resets the counter and emits a "fresh" buff toast.
6. **Downtown core**: a new `buildDowntownCore()` pass spawns 6â€“10 tall skyscrapers (40â€“80m) with neon billboards in the four central lots adjacent to origin, reusing the existing skyscraper geometry from `buildBuilding`.
7. **Road-facing rotation**: replace the existing `Math.atan2(-cfg.pos[0], -cfg.pos[1])` "face origin" math with a `nearestRoadFacing(cx, cz)` helper that finds the closest avenue/street line and rotates the building so its local +Z (door direction) points at it.

