  page.on('console', m => { if (m.type() === 'error') errs.push('console.error: ' + m.text()); });

  await page.goto('http://localhost:3000/finlife-3d.html', { waitUntil: 'networkidle' });
  await page.click('#btn-start');
  await page.waitForTimeout(1500);

  const counts = await page.evaluate(() => {
    const f3 = window.__finlife3d;
    return {
      buildings: f3._getBuildings().length,
      stores: f3._getStores().length,
      assigned: f3._getBuildings().filter(b => b.isCityFiller && b.storeIdx !== undefined).length,
    };
  });
  console.log('counts:', JSON.stringify(counts));

  // Top-down to verify signage rendered
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 0; p.y = 200; p.z = 0; p.yaw = 0; p.pitch = -1.4;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-storesigns.png' });

