  const entered = await page.evaluate(() => {
    const f3 = window.__finlife3d;
    const filler = f3._getBuildings().find(b => b.isCityFiller && b.storeIdx !== undefined);
    if (!filler) return null;
    f3._enterStore(filler);
    return { storeIdx: filler.storeIdx, store: f3._getStores()[filler.storeIdx] };
  });
  console.log('entered:', JSON.stringify(entered));
  await page.waitForTimeout(400);
  await page.screenshot({ path: '.shot-store-interior.png' });

  // Try buying the nearest item
  const beforeBelongings = await page.evaluate(() => (GS.char.belongings||[]).length);
  // Move player to a shelf item
  await page.evaluate(() => {
    const items = window.__finlife3d_stores;
    const list = items && (function(){ try { return storeShelfItems; } catch(e){ return null; } })();
    // We can't access storeShelfItems directly from here; instead pick first item's pos via a hook
  });
  // Instead, simulate: walk forward inside store and press F a few times
  for (let i = 0; i < 8; i++){
    await page.keyboard.down('w');
    await page.waitForTimeout(80);
    await page.keyboard.up('w');
  }
  await page.keyboard.press('f');
  await page.waitForTimeout(200);
  const afterBelongings = await page.evaluate(() => (GS.char.belongings||[]).length);

  // Walk back to door and exit
