  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-storesigns.png' });

  // Walk to a store filler at street level
  const storeFillerInfo = await page.evaluate(() => {
    const f3 = window.__finlife3d;
    const filler = f3._getBuildings().find(b => b.isCityFiller && b.storeIdx !== undefined);
    if (!filler) return null;
    const p = f3._getPlayer();
    p.x = filler.pos.x + 5; p.y = 1.6; p.z = filler.pos.z; p.yaw = -Math.PI/2; p.pitch = 0;
    return { storeIdx: filler.storeIdx, store: f3._getStores()[filler.storeIdx], pos: [filler.pos.x, filler.pos.z] };
  });
  console.log('storeFiller:', JSON.stringify(storeFillerInfo));
  await page.waitForTimeout(200);
  await page.screenshot({ path: '.shot-storefront.png' });

  // Force-enter the store
  await page.evaluate(() => {
    const f3 = window.__finlife3d;
    const filler = f3._getBuildings().find(b => b.isCityFiller && b.storeIdx !== undefined);
    f3._enterStore(filler);
  });
  await page.waitForTimeout(400);

  // Move player INTO the store toward the shelves
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 0; p.y = 1.6; p.z = 4; p.yaw = 0; p.pitch = -0.05;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-store-aisle.png' });

  // Directly buy the first available shelf item via the registered helper
  const buyResult = await page.evaluate(() => {
    const stores = window.__finlife3d_stores;
    // We need access to storeShelfItems â€” exposed via findNearestStoreItem after teleporting near one
    // Move player next to a shelfItem
    // We don't have a direct getter, but findNearestStoreItem returns one if within 1.6m.
    // Try several positions to land near a shelf.
    const p = window.__finlife3d._getPlayer();
    const candidates = [
      [-6, 2.2], [-2, 2.2], [2, 2.2], [6, 2.2],
      [-6, -2.2], [-2, -2.2], [2, -2.2], [6, -2.2],
    ];
    for (const [x, z] of candidates) {
      p.x = x; p.z = z;
      const si = stores.findNearestStoreItem();
      if (si) {
        const beforeMoney = (GS.char.checking||0) + (GS.char.savings||0);
        const beforeBel = (GS.char.belongings||[]).length;
        stores.buyStoreItem(si);
        const afterMoney = (GS.char.checking||0) + (GS.char.savings||0);
        const afterBel = (GS.char.belongings||[]).length;
        return { item: si.item, beforeMoney, afterMoney, beforeBel, afterBel };
      }
    }
    return { found: false };
  });
  console.log('buy:', JSON.stringify(buyResult));

  // Exit
  await page.evaluate(() => window.__finlife3d._exitStore());
  await page.waitForTimeout(150);
  const stillIn = await page.evaluate(() => window.__finlife3d._isInStore());
  console.log('still in store after exit:', stillIn);

  if (errs.length) { console.log('ERRORS:'); errs.forEach(e => console.log(' ' + e)); }
  else console.log('No JS errors');

  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

