tool_input.content:
const path = require('path');
const pw = require(path.join(process.cwd(), '.playwright-cli', 'node_modules', 'playwright-core'));

(async () => {
  const browser = await pw.chromium.launch({ headless: true });
  const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errs.push('console.error: ' + m.text()); });

  await page.goto('http://localhost:3000/finlife-3d.html', { waitUntil: 'networkidle' });
  await page.click('#btn-start');
  await page.waitForTimeout(1500);

  // Top-down shot of the stadium plot
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 15; p.y = 60; p.z = -75; p.yaw = 0; p.pitch = -1.4;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-stadium-top.png' });

  // Eye-level shot from the south plaza, looking north into the stadium
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 15; p.y = 1.6; p.z = -55; p.yaw = Math.PI; p.pitch = 0.05;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-stadium-front.png' });

  // Elevated angled shot showing the bowl
  await page.evaluate(() => {
    const p = window.__finlife3d._getPlayer();
    p.x = 35; p.y = 18; p.z = -55; p.yaw = -Math.PI*0.85; p.pitch = -0.35;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.shot-stadium-angle.png' });

  if (errs.length) { console.log('ERRORS:'); errs.forEach(e => console.log(' ' + e)); }
  else console.log('No JS errors');
  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

