const path = require('path');
const pw = require(path.join(process.cwd(), '.playwright-cli', 'node_modules', 'playwright-core'));

(async () => {
  const browser = await pw.chromium.launch({ headless: true });
  const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errs.push('console.error: ' + m.text()); });

  await page.goto('http://localhost:3000/finlife-3d.html', { waitUntil: 'networkidle' });
  await page.click('#btn-start');
  await page.waitForTimeout(1000);

  // Open phone, tap Block Trade
  await page.keyboard.press('e');
  await page.waitForTimeout(200);
  await page.click('#phone-home button[data-app="blocktrade"]');
  await page.waitForTimeout(800);

  const status = await page.evaluate(() => {
    const ifr = document.querySelector('#phone-app-content iframe');
    return {
      iframePresent: !!ifr,
      iframeSrc: ifr ? ifr.getAttribute('src') : null,
      fullbleed: document.getElementById('phone-app-content').dataset.fullbleed === '1',
      backShown: document.getElementById('phone-back').classList.contains('show'),
    };
  });
  console.log('after-tap:', JSON.stringify(status));
  await page.screenshot({ path: '.shot-bt.png' });

  // Verify game inside iframe loaded
  const innerLoaded = await page.evaluate(() => {
    const ifr = document.querySelector('#phone-app-content iframe');
    if (!ifr) return false;
    try {
      return !!(ifr.contentDocument && ifr.contentDocument.body);
    } catch(e){ return 'cross-origin (unexpected)'; }
  });
  console.log('inner doc loaded:', innerLoaded);

  // Tap back, tap Block Trade again, assert iframe identity preserved
  const beforeBack = await page.evaluate(() => {
    const ifr = document.querySelector('#phone-app-content iframe');
    ifr.dataset.testStamp = String(Date.now());
    return ifr.dataset.testStamp;
  });
  await page.click('#phone-back');
  await page.waitForTimeout(200);
  await page.click('#phone-home button[data-app="blocktrade"]');
  await page.waitForTimeout(300);
  const afterReopen = await page.evaluate(() => {
    const ifr = document.querySelector('#phone-app-content iframe');
    return ifr ? ifr.dataset.testStamp : null;
  });
  console.log('iframe persisted across back/home:', beforeBack === afterReopen);

  if (errs.length) { console.log('ERRORS:'); errs.forEach(e => console.log(' ' + e)); }
  else console.log('No JS errors');
  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

