const path = require('path');
const pw = require(path.join(process.cwd(), '.playwright-cli', 'node_modules', 'playwright-core'));

(async () => {
  const browser = await pw.chromium.launch({ headless: true });
  const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errs.push('console.error: ' + m.text()); });

  await page.goto('http://localhost:3000/finlife-3d.html', { waitUntil: 'networkidle' });
  await page.click('#btn-start');
  await page.waitForTimeout(1500);

  // 1. Sponsors building should NOT exist in 3D
  const sponsorsExists = await page.evaluate(() => {
    const f3 = window.__finlife3d;
    return f3.BUILDINGS.some(b => b.id === 'sponsors');
  });
  console.log('sponsors still in BUILDINGS array:', sponsorsExists);

  // 2. Inject a business >250K and a sport job, then trigger tickSponsors a few times
  const injection = await page.evaluate(() => {
    if (!GS.inv) GS.inv = {};
    if (!GS.inv.businesses) GS.inv.businesses = [];
    GS.inv.businesses.push({ id:'biz1', name:'Test Cafe', value: 400000 });
    GS.char.employed = true;
    GS.char.jobTitle = 'NBA Point Guard';
    GS.char.sportsAwards = 2;
    return { biz: GS.inv.businesses.length, job: GS.char.jobTitle, awards: GS.char.sportsAwards };
  });
  console.log('injected:', JSON.stringify(injection));

  // Trigger ticks by directly calling btn-age multiple times
  for (let i = 0; i < 30; i++){
    await page.evaluate(() => document.getElementById('btn-age').click());
    await page.waitForTimeout(50);
  }

  // 3. Check inbox accumulated sponsor offers
  const sponsState = await page.evaluate(() => {
    const offers = (GS.inbox||[]).filter(i => i && i.category === 'sponsor');
    return {
      totalSponsorMessages: offers.length,
      pendingCount: offers.filter(i => !i.offer.accepted && !i.offer.declined).length,
      sample: offers[0] ? { name: offers[0].name, kind: offers[0].offer.kind, deal: offers[0].offer.deal } : null,
    };
  });
  console.log('sponsor inbox state:', JSON.stringify(sponsState));

  // 4. Open phone, check yellow badge appears on inbox app
  await page.keyboard.press('e');
  await page.waitForTimeout(300);
  const badgeInfo = await page.evaluate(() => {
    const badge = document.querySelector('#phone-home button.inbox .spons-badge');
    return badge ? { count: badge.textContent, visible: getComputedStyle(badge).display !== 'none' } : null;
  });
  console.log('yellow badge:', JSON.stringify(badgeInfo));

  // 5. Click the badge â†’ sponsor offers modal opens
  if (badgeInfo) {
    await page.click('#phone-home button.inbox .spons-badge');
    await page.waitForTimeout(300);
    const modalOpen = await page.evaluate(() => !!document.getElementById('spons-overlay'));
    console.log('sponsor modal opened:', modalOpen);

    // Accept the first offer
    const accepted = await page.evaluate(() => {
      const btn = document.querySelector('#spons-overlay button[data-act="accept"]');
      if (!btn) return null;
      const id = btn.dataset.id;
      const beforeMoney = GS.char.checking || 0;
      btn.click();
      return { id, beforeMoney };
    });
    await page.waitForTimeout(200);
    const afterAccept = await page.evaluate(() => {
      const item = (GS.inbox||[]).find(i => i.offer && i.offer.accepted);
      const biz = (GS.inv.businesses||[]).find(b => b.sponsored);
      return {
        anyAccepted: !!item,
        moneyAfter: GS.char.checking,
        sponsoredBiz: biz ? { name: biz.name, value: biz.value, brand: biz.sponsorBrand } : null,
      };
    });
    console.log('after accept:', JSON.stringify(afterAccept));

    // Trigger another tick â€” sponsored business value should grow ~8.33%
    const beforeTickValue = afterAccept.sponsoredBiz?.value;
    await page.evaluate(() => document.getElementById('btn-age').click());
    await page.waitForTimeout(100);
    const afterTickValue = await page.evaluate(() => (GS.inv.businesses||[]).find(b => b.sponsored)?.value);
    const ratio = afterTickValue && beforeTickValue ? afterTickValue / beforeTickValue : null;
    console.log('biz value before/after tick:', beforeTickValue, '->', afterTickValue, 'ratio:', ratio?.toFixed(5));
  }

  // 6. Joystick visibility (force narrow viewport)
  await page.setViewportSize({ width: 480, height: 800 });
  await page.waitForTimeout(150);
  const joystickShown = await page.evaluate(() => {
    const ms = document.getElementById('mob-stick');
    return ms ? getComputedStyle(ms).display !== 'none' : null;
  });
  console.log('joystick visible on mobile width:', joystickShown);

  if (errs.length) { console.log('ERRORS:'); errs.forEach(e => console.log(' ' + e)); }
  else console.log('No JS errors');
  await browser.close();
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

