function createBoxer3D(opts){
  const root = new THREE.Group();
  const skinMat = new THREE.MeshLambertMaterial({ color: opts.skin });
  const trunkMat = new THREE.MeshLambertMaterial({ color: opts.trunks });
  const beltMat = new THREE.MeshLambertMaterial({ color: 0xffd700 });
  const bootMat = new THREE.MeshLambertMaterial({ color: 0x111111 });
  const gloveMat = new THREE.MeshLambertMaterial({ color: opts.gloveColor });
  const hairMat = new THREE.MeshLambertMaterial({ color: 0x1a0d0d });

  // Boots
  const bootL = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.32), bootMat);
  bootL.position.set(0, 0.06, -0.13);
  root.add(bootL);
  const bootR = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.32), bootMat);
  bootR.position.set(0, 0.06, 0.13);
  root.add(bootR);
  // Legs (trunks)
  const legL = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.14, 0.85, 8), trunkMat);
  legL.position.set(0, 0.55, -0.13);
  root.add(legL);
  const legR = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.14, 0.85, 8), trunkMat);
  legR.position.set(0, 0.55, 0.13);
  root.add(legR);
  // Belt (gold waistband)
  const belt = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.1, 0.42), beltMat);
  belt.position.set(0, 1.02, 0);
  root.add(belt);
  // Torso
  const torso = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.7, 0.4), skinMat);
  torso.position.set(0, 1.42, 0);
  root.add(torso);
  // Pec separation (subtle dark line)
  const pecLine = new THREE.Mesh(
    new THREE.BoxGeometry(0.025, 0.5, 0.005),
    new THREE.MeshLambertMaterial({ color: 0x6a4a30 })
  );
  pecLine.position.set(0, 1.42, 0.21);
  root.add(pecLine);
  // Head
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 14, 10), skinMat);
  head.position.set(0, 1.95, 0);
  root.add(head);
  // Hair cap
  const hair = new THREE.Mesh(
    new THREE.SphereGeometry(0.225, 14, 8, 0, Math.PI*2, 0, Math.PI/2.2),
    hairMat
  );
  hair.position.set(0, 1.97, 0);
  root.add(hair);
  // Eyes
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000 });
  const eyeL = new THREE.Mesh(new THREE.SphereGeometry(0.025, 6, 6), eyeMat);
  eyeL.position.set(0.20, 1.96, -0.07);
  root.add(eyeL);
  const eyeR = new THREE.Mesh(new THREE.SphereGeometry(0.025, 6, 6), eyeMat);
  eyeR.position.set(0.20, 1.96, 0.07);
  root.add(eyeR);
  // Mouth (subtle line)
  const mouth = new THREE.Mesh(
    new THREE.BoxGeometry(0.005, 0.025, 0.07),
    new THREE.MeshLambertMaterial({ color: 0x4a1a1a })
  );
  mouth.position.set(0.21, 1.86, 0);
  root.add(mouth);

  // â”€â”€ ARMS â€” sub-groups so we can rotate from the shoulder
  // Arm orientation: at rest, both arms in guard position (gloves up by face).
  // We model arm as a "shoulder group" that pivots around shoulder, with
  // a forearm cylinder + glove sphere as its children.
  function buildArm(side){
    // side: -1 (back / left) or +1 (front / right)
    const shoulder = new THREE.Group();
    shoulder.position.set(0, 1.62, side * 0.32); // shoulder anchor
    const forearm = new THREE.Mesh(
      new THREE.CylinderGeometry(0.08, 0.075, 0.5, 8),
      skinMat
    );
    // Forearm is a vertical cylinder; we orient and offset it by a child group
    const armPivot = new THREE.Group();
    forearm.position.set(0.25, 0, 0); // extends along +X by 0.25 from pivot
    forearm.rotation.z = Math.PI/2; // align cylinder along X
    armPivot.add(forearm);
    const glove = new THREE.Mesh(
      new THREE.SphereGeometry(0.135, 14, 10),
      gloveMat
    );
    glove.position.set(0.5, 0, 0); // glove at end of arm
    armPivot.add(glove);
    // White stripe on glove
    const stripe = new THREE.Mesh(
      new THREE.TorusGeometry(0.135, 0.02, 6, 18),
      new THREE.MeshLambertMaterial({ color: 0xffffff })
    );
    stripe.position.copy(glove.position);
    stripe.rotation.y = Math.PI/2;
    armPivot.add(stripe);

    shoulder.add(armPivot);
    root.add(shoulder);
    return { shoulder, armPivot, forearm, glove };
  }
  // "Lead" arm = front arm (closer to camera in side view = +Z side)
  const leadArm = buildArm(+1);
  const rearArm = buildArm(-1);

  // Default guard pose (gloves raised in front of face)
  function setGuardPose(){
    leadArm.shoulder.rotation.set(0, 0, -1.0);
    leadArm.shoulder.position.set(0.05, 1.62, 0.28);
    rearArm.shoulder.rotation.set(0, 0, -1.1);
    rearArm.shoulder.position.set(-0.05, 1.62, -0.28);
    leadArm.armPivot.rotation.set(0, 0, 0);
    rearArm.armPivot.rotation.set(0, 0, 0);
  }
  setGuardPose();

  // Shadow disc
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.5, 16),
    new THREE.MeshBasicMaterial({ color: 0x000, transparent: true, opacity: 0.5 })
  );
  shadow.rotation.x = -Math.PI/2;
  shadow.position.y = 0.012;
  root.add(shadow);

  return {
    root, head, torso, leadArm, rearArm, setGuardPose,
  };
}

