// â”€â”€ Leg segment helper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Draws hipâ†’kneeâ†’foot as two thick rectangles meeting at a knee joint
function drawLegSegs(hx, hy, kx, ky, fx, fy, w, color){
  function seg(ax, ay, bx, by, hw){
    const a = Math.atan2(by - ay, bx - ax);
    const px = Math.sin(a) * hw, py = Math.cos(a) * hw;
    ctx.beginPath();
    ctx.moveTo(ax - px, ay + py);
    ctx.lineTo(bx - px, by + py);
    ctx.lineTo(bx + px, by - py);
    ctx.lineTo(ax + px, ay - py);
    ctx.closePath();
    ctx.fill();
  }
  ctx.fillStyle = color;
  seg(hx, hy, kx, ky, w / 2);       // thigh
  seg(kx, ky, fx, fy, w / 2 - 1.5); // shin (slightly thinner)
}

