  const leftFootDX  =  Math.sin(b.legPhase * Math.PI * 2) * stepAmt;
  const rightFootDX =  Math.sin(b.legPhase * Math.PI * 2 + Math.PI) * stepAmt;

  ctx.save();
  ctx.translate(x, y - flinchY - bobY);
  if (koProg > 0){
